          if (Array.isArray(stackPath)) {
            mpxStackPath = stackPath
          }
        }
      } catch (e) {
      }
    }
    global.__mpxRouter.stack = mpxStackPath
    global.__mpxRouter.lastStack = null
    global.__mpxRouter.needCache = null
    global.__mpxRouter.needRemove = []
